import{_ as a,o as e,c as r,a6 as o}from"./chunks/framework.De615z8S.js";const p=JSON.parse('{"title":"跨境本地化：英文、日文、单位与准确文字","description":"","frontmatter":{"id":"localization","title":"跨境本地化：英文、日文、单位与准确文字","chapter":"03","topic":"cross-border","status":"已公开","evidence_status":"原创教程与规划示范，尚未执行图像任务或后台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["ecommerce-skills","visual-copywriting","cross-border-knowledge"],"platform_rule_ids":[],"order":23.6},"headers":[],"relativePath":"ecommerce/localization.md","filePath":"ecommerce/localization.md"}'),d={name:"ecommerce/localization.md"};function i(l,t,n,s,h,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="跨境本地化-英文、日文、单位与准确文字" tabindex="-1">跨境本地化：英文、日文、单位与准确文字 <a class="header-anchor" href="#跨境本地化-英文、日文、单位与准确文字" aria-label="Permalink to &quot;跨境本地化：英文、日文、单位与准确文字&quot;">​</a></h1><p>先做事实对照，再调整表达和版式。同一个参数翻译后仍是同一个参数；市场不同并不允许改变商品材质、尺寸、配件或性能。</p><h2 id="第1步-建立词表与事实列" tabindex="-1">第1步：建立词表与事实列 <a class="header-anchor" href="#第1步-建立词表与事实列" aria-label="Permalink to &quot;第1步：建立词表与事实列&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>中文母表</th><th>英文练习</th><th>日文练习</th></tr></thead><tbody><tr><td>商品</td><td>带盖桌面收纳盒</td><td>Desk organizer with lid</td><td>ふた付きデスク収納ボックス</td></tr><tr><td>结构</td><td>可拆隔板</td><td>Removable divider</td><td>取り外し可能な仕切り</td></tr><tr><td>外尺寸</td><td>长220×宽150×高120 mm</td><td>External size: L220 × W150 × H120 mm</td><td>外寸：長さ220 × 幅150 × 高さ120 mm</td></tr><tr><td>发货</td><td>盒体1、盖子1、隔板1</td><td>Box ×1, lid ×1, divider ×1</td><td>本体1点、ふた1点、仕切り1点</td></tr></tbody></table><p>这里是虚构DN01的填写示范，不是已审定商业译稿。正式使用时让熟悉目标语言与类目的人复核自然表达、术语和准确事实。使用<a href="/ai-visual-creation-handbook/prompts/P16">P16英文</a>或<a href="/ai-visual-creation-handbook/prompts/P17">P17日文</a>，分别输出译文、回译和需要确认的词。</p><h2 id="第2步-尺寸计算单独处理" tabindex="-1">第2步：尺寸计算单独处理 <a class="header-anchor" href="#第2步-尺寸计算单独处理" aria-label="Permalink to &quot;第2步：尺寸计算单独处理&quot;">​</a></h2><p>国际英寸与毫米的换算是1 in = 25.4 mm。DN01外尺寸换算并四舍五入到两位：220 mm约8.66 in，150 mm约5.91 in，120 mm约4.72 in。<a href="https://www.nist.gov/pml/owm/si-units-length" target="_blank" rel="noreferrer">NIST长度单位说明</a>。</p><p>保留原值、公式、舍入位数和长宽高标签，使用<a href="/ai-visual-creation-handbook/prompts/P18">P18</a>。英寸近似值不代替原始测量；不同品牌服装的S/M/L不能仅凭这条公式互换。</p><h2 id="第3步-准确文字与版式" tabindex="-1">第3步：准确文字与版式 <a class="header-anchor" href="#第3步-准确文字与版式" aria-label="Permalink to &quot;第3步：准确文字与版式&quot;">​</a></h2><p>短标签需要图中呈现时，先排一份可编辑文字稿。长句可以放网页文本区；日文换行不拆关键术语，英文避免因为缩小字号而读不清。模型输出的文字逐字对照，不因整体视觉好看就跳过。</p><p>用主题文本／PS／Krita独立文字层排版，保留语言版本。包装原文若需改成另一个语言版本，先确认真实包装是否存在该版本；不能为了本地化改造真实商品标识。</p><h2 id="第4步-每项声明找依据" tabindex="-1">第4步：每项声明找依据 <a class="header-anchor" href="#第4步-每项声明找依据" aria-label="Permalink to &quot;第4步：每项声明找依据&quot;">​</a></h2><p>“ABS”只说明练习材质，不推出食品级、无毒或可回收。“可拆隔板”不推出可承重或耐温。场景标题是创作表达，数值和功能仍回到事实表。最终交付对照表、准确文字和未确认项，不自动承诺翻译或平台合规完全通过。</p>',13)])])}const _=a(d,[["render",i]]);export{p as __pageData,_ as default};
